// Checks `data-*` props on the marks app (rt-test/marks, generated by
// plan2cpp): native_props writes a node's words as the runner does, the
// agent's `nodes` op shows them, an extension reads them by word through its
// generated `data_<word>` methods (`Runtime::marks`), they follow state, and
// the `extensions` op lists the props an extension declares. Prints each
// failure; exit 0 when all pass.
#include <cstdio>
#include <string>
#include <vector>

#include "exact_rt.h"
#include "ext_marks.h"

namespace app {
extern const rt::App kApp;
}

namespace {

class Clock : public rt::Board {
 public:
  int64_t micros() const override { return 0; }
};

class Marks : public ext::MarksExtension {
 public:
  using MarksExtension::data_count;
  using MarksExtension::data_mode;
  using MarksExtension::data_snap;
  using MarksExtension::data_snap_align;
};

int failures = 0;

void expect(bool ok, const std::string& what) {
  if (!ok) {
    ++failures;
    std::printf("FAIL %s\n", what.c_str());
  }
}

bool contains(const std::string& text, const std::string& part) { return text.find(part) != std::string::npos; }

// The marks as "testId=value" items, for one comparison.
std::string list(const std::vector<rt::Mark>& marks) {
  std::string out;
  for (const rt::Mark& m : marks) out += (out.empty() ? "" : " ") + m.test_id + "=" + m.value;
  return out;
}

// The runner's NativeProps rules (Exact runner/src/stdlib.rs): every value a
// string, a number as JavaScript prints it, none left out, JSON escaping.
void check_native_props() {
  const rt::V pairs[] = {
      rt::V::str("a"), rt::V::num(1.5), rt::V::str("b"), rt::V(),
      rt::V::str("c"), rt::V::boolean(true), rt::V::str("d"), rt::V::str("q\"\\\t\x01"),
  };
  const std::string json = rt::native_props(pairs, 4).s;
  expect(json == "{\"a\":\"1.5\",\"c\":\"true\",\"d\":\"q\\\"\\\\\\t\\u0001\"}", "native_props wrote " + json);
  std::string value;
  expect(rt::data_word(json, "d", value) && value == "q\"\\\t\x01", "data_word reads an escaped value back");
  expect(rt::data_word(json, "a", value) && value == "1.5", "data_word reads the first word");
  expect(!rt::data_word(json, "b", value), "a none value has no word");
  expect(!rt::data_word(json, "e", value), "an absent word is not found");
  expect(!rt::data_word("", "a", value), "an empty dataset has no words");
  expect(!rt::data_word("{\"a\":", "a", value), "a cut dataset has no words");
  expect(rt::native_props(pairs, 0).s == "{}", "no pairs write an empty object");
}

void check_app(bool bound) {
  const std::string name = bound ? "bound" : "not bound";
  Clock board;
  Marks marks;
  std::vector<rt::Extension*> extensions;
  if (bound) extensions.push_back(&marks);
  rt::Runtime runtime(app::kApp, board, extensions);
  expect(runtime.boot(), name + ": boot");
  const std::string nodes = runtime.agent("{\"op\":\"nodes\"}");
  expect(contains(nodes, "{\"testId\":\"list\",\"text\":\"\",\"data\":{\"snap\":\"y\"},\"inactive\":false}"),
         name + ": an absent option leaves its word out: " + nodes);
  expect(contains(nodes, "\"testId\":\"a\",\"text\":\"a\",\"data\":{\"count\":\"2\",\"snap-align\":\"center\"}"),
         name + ": words are sorted: " + nodes);
  expect(contains(nodes, "{\"testId\":\"grow\",\"text\":\"\",\"inactive\":false}"), name + ": no words, no data: " + nodes);
  expect(list(marks.data_snap(runtime)) == "list=y", name + ": snap is " + list(marks.data_snap(runtime)));
  expect(list(marks.data_snap_align(runtime)) == "a=center b=start",
         name + ": snap-align is " + list(marks.data_snap_align(runtime)));
  expect(list(marks.data_mode(runtime)).empty(), name + ": mode before grow");
  expect(runtime.tap("grow"), name + ": tap grow");
  runtime.tick();
  expect(list(marks.data_count(runtime)) == "a=3", name + ": count follows state: " + list(marks.data_count(runtime)));
  expect(list(marks.data_mode(runtime)) == "list=wide", name + ": mode after grow: " + list(marks.data_mode(runtime)));
  const std::string listed = runtime.agent("{\"op\":\"extensions\"}");
  const std::string props = bound ? "\"props\":[\"snap\",\"snap-align\",\"mode\",\"count\"]" : "\"props\":[]";
  expect(contains(listed, props), name + ": extensions " + listed);
}

}  // namespace

int main() {
  check_native_props();
  check_app(true);
  check_app(false);
  std::printf("data_check: %s\n", failures ? "failures" : "all checks pass");
  return failures ? 1 : 0;
}
